def evaluar(clf, X_train, y_train, X_test, y_test):
    pipe = make_pipeline(StandardScaler(), clf)
    pipe.fit(X_train, y_train)
    y_pred = pipe.predict(X_test)
    return {
        "accuracy": accuracy_score(y_test, y_pred),
        "precision_toxico": precision_score(y_test, y_pred, zero_division=0),
        "recall_toxico": recall_score(y_test, y_pred, zero_division=0),
        "f1_toxico": f1_score(y_test, y_pred, zero_division=0),
        "mcc": matthews_corrcoef(y_test, y_pred),
    }, y_pred


resultados = []
predicciones = {}

for nombre, clf in classifiers.items():
    supports_cw = "class_weight" in inspect.signature(clf.__class__).parameters
    configs = {"default": {}} if not supports_cw else {"None": {"class_weight": None}, "'balanced'": {"class_weight": "balanced"}}

    for config_nombre, params in configs.items():
        t0 = time.time()
        try:
            clf_actual = clone(clf)  # copia limpia, sin entrenar, con los mismos hiperparámetros
            if params:
                clf_actual.set_params(**params)
            metrics, y_pred = evaluar(clf_actual, X_train, y_train, X_test, y_test)
            metrics["tiempo_s"] = round(time.time() - t0, 2)
            metrics["clasificador"] = nombre
            metrics["class_weight"] = config_nombre
            resultados.append(metrics)
            predicciones[f"{nombre} ({config_nombre})"] = y_pred
        except Exception as e:
            print(f"[{nombre} / {config_nombre}] falló: {type(e).__name__}: {e}")

resultados_df = pd.DataFrame(resultados)[
    ["clasificador", "class_weight", "accuracy", "precision_toxico", "recall_toxico", "f1_toxico", "mcc", "tiempo_s"]
].sort_values("mcc", ascending=False).reset_index(drop=True)

